using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

namespace McpServer.Tools;

[McpServerToolType]
public sealed class ApiFetchTool
{
    [McpServerTool("api_fetch"), Description("Fetches data from an external API endpoint.")]
    public static async Task<string> FetchAsync(
        HttpClient httpClient,
        ILogger<ApiFetchTool> logger,
        [Description("Relative path to the API resource (e.g. /users/1)")] string path,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching API resource: {Path}", path);

        var response = await httpClient.GetAsync(path, cancellationToken);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>(cancellationToken);
        return JsonSerializer.Serialize(json, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public sealed class SummarizePrompt
{
    [McpServerPrompt("summarize"), Description("Summarizes the provided text at a chosen detail level.")]
    public static IList<ChatMessage> Summarize(
        [Description("The text to summarize")] string text,
        [Description("Detail level: brief, standard, or detailed")] string level = "standard")
    {
        return
        [
            new ChatMessage(
                ChatRole.User,
                $$"""
                Summarize the following text.
                Detail level: {{level}}

                ---
                {{text}}
                """)
        ];
    }
}

